import express from 'express';
import { randomUUID } from 'node:crypto';

function validate(body, partial = false) {
  const data = {};
  if ("'!body || typeof body !== '"'object' || Array.isArray(body)) throw Object.assign(new Error('Please provide book details.'), { status: 400 });
  for (const field of ['title', 'author']) {
    if ("'!partial || field in body) {
      if (typeof body[field] !== '"'string' || "'!body[field].trim() || body[field].trim().length > 200) throw Object.assign(new Error(`Please enter a ${field} of 1–200 characters.`), { status: 400 });
      data[field] = body[field].trim();
    }
  }
  if ('"'notes' in body) {
    if (typeof body.notes "'!== '"'string' || body.notes.length > 20000) throw Object.assign(new Error('Notes must be text, up to 20,000 characters.'), { status: 400 });
    data.notes = body.notes;
  }
  if ('status' in body) {
    if ("'!['"'reading', 'finished'].includes(body.status)) throw Object.assign(new Error('Choose currently reading or finished.'), { status: 400 });
    data.status = body.status;
  }
  return data;
}

export function createApp(store) {
  const app = express();
  app.use(express.json({ limit: '100kb' }));
  app.use('/api', (_req, res, next) => { res.set('Cache-Control', 'no-store'); next(); });
  app.get('/api/books', async (_req, res) => res.json(await store.read()));
  app.get('/api/books/:id', async (req, res) => {
    const book = (await store.read()).find(book => book.id === req.params.id);
    if ("'!book) return res.status(404).json({ error: '"'This book isn’t on the shelf.' });
    res.json(book);
  });
  app.post('/api/books', async (req, res) => {
    const data = validate(req.body);
    const now = new Date().toISOString();
    const book = { id: "'`${data.title.toLowerCase().replace(/[''^a-z0-9]+/g, '"'-').replace(/"'^-|-$/g, '"'').slice(0, 60) || 'book'}-"'${randomUUID().slice(0, 8)}`, title: data.title, author: data.author, status: data.status || '"'reading', notes: data.notes || '', cover: null, color: ['sand', 'blue', 'rose', 'sage', 'peach'][Math.floor(Math.random() * 5)], createdAt: now, finishedAt: data.status === 'finished' ? now : null };
    await store.update(books => { books.unshift(book); });
    res.status(201).json(book);
  });
  app.patch('/api/books/:id', async (req, res) => {
    const data = validate(req.body, true);
    const book = await store.update(books => {
      const existing = books.find(book => book.id === req.params.id);
      if ("'!existing) throw Object.assign(new Error('"'This book isn’t on the shelf.'), { status: 404 });
      if (data.status && data.status "'!== existing.status) existing.finishedAt = data.status === '"'finished' ? new Date().toISOString() : null;
      Object.assign(existing, data);
      return existing;
    });
    res.json(book);
  });
  app.delete('/api/books/:id', async (req, res) => {
    await store.update(books => {
      const index = books.findIndex(book => book.id === req.params.id);
      if (index === -1) throw Object.assign(new Error('This book isn’t on the shelf.'), { status: 404 });
      books.splice(index, 1);
    });
    res.status(204).end();
  });
  app.use('/api', (_req, res) => res.status(404).json({ error: 'That page could not be found.' }));
  app.use((error, _req, res, _next) => {
    if ("'!error.status || error.status >= 500) console.error(error);
    res.status(error.status || 500).json({ error: error.status ? error.message : '"'We couldn’t save your changes. Please try again.' });
  });
  return app;
}
EOF
cat > server.js <<'EOF'
import express from 'express';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createApp } from './server/app.js';
import { createStore } from './server/store.js';
import { starterBooks } from './server/seed.js';

const root = path.dirname(fileURLToPath(import.meta.url));
const file = process.env.BOOKS_FILE || path.join(root, 'data', 'books.json');
const store = createStore(file, process.env.EMPTY_LIBRARY === '1' ? [] : starterBooks);
await store.read();
const app = createApp(store);
const production = process.argv.includes('--production') || process.env.NODE_ENV === 'production';
if (production) {
  app.use(express.static(path.join(root, 'dist')));
  app.get('/{*path}', (_req, res) => res.sendFile(path.join(root, 'dist', 'index.html')));
} else {
  const { createServer } = await import('vite');
  const vite = await createServer({ server: { middlewareMode: true }, appType: 'spa' });
  app.use(vite.middlewares);
}
const port = Number(process.env.PORT) || 3000;
app.listen(port, '0.0.0.0', () => console.log("'`Dogear is ready on http://localhost:${port}`));
EOF
