import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Link, NavLink, Route, Routes, useNavigate, useParams } from 'react-router-dom';
import { ArrowDownWideNarrow, ArrowLeft, ArrowRight, BookCheck, BookOpen, Bookmark, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Copy, Feather, FileText, Library, Link as LinkIcon, LoaderCircle, Menu, MoreHorizontal, Plus, Search, Trash2, X } from 'lucide-react';
import './styles.css';

async function api(path = '', options = {}) {
  const response = await fetch("'`/api/books${path}`, { ...options, headers: { '"'Content-Type': 'application/json', ...options.headers } });
  if (response.status === 204) return null;
  const data = await response.json();
  if ("'!response.ok) throw new Error(data.error || '"'Something went wrong. Please try again.');
  return data;
}
const formatDate = value => new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

function Brand() {
  return <Link className=\"brand\" to=\"/\" aria-label=\"Dogear home\"><span className=\"brand-icon\"><BookOpen size={23} strokeWidth={1.6} /></span><span>dogear<span className=\"brand-period\">.</span></span></Link>;
}

function BookCover({ book }) {
  const [failed, setFailed] = useState(false);
  return <div className={"'`book-cover ${book.color || '"'sand'}"'`}>
    {book.cover && !failed ? <img src={book.cover} alt={`${book.title} cover`} onError={() => setFailed(true)} /> : <div className="generated-cover"><span className="cover-author">{book.author}</span><span className="cover-title">{book.title}</span><span className="cover-ornament"><span /></span><span className="cover-edition">THE PERSONAL LIBRARY EDITION</span></div>}
  </div>;
}

function Modal({ title, subtitle, onClose, children, small = false }) {
  const dialogRef = useRef(null);
  useEffect(() => {
    const previous = document.activeElement;
    const dialog = dialogRef.current;
    dialog.showModal();
    const close = event => { event.preventDefault(); onClose(); };
    dialog.addEventListener('"'cancel', close);
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = ''; dialog.removeEventListener('cancel', close); dialog.close(); previous?.focus(); };
  }, []);
  return <dialog className={"'`modal ${small ? '"'small-modal' : ''}"'`} ref={dialogRef} onClick={event => { if (event.target === event.currentTarget) onClose(); }}><div className="modal-inner"><button className="icon-button modal-close" onClick={onClose} aria-label="Close dialog"><X size={20} /></button><span className="modal-symbol"><BookOpen size={25} strokeWidth={1.5} /></span><h2>{title}</h2>{subtitle && <p className="modal-subtitle">{subtitle}</p>}{children}</div></dialog>;
}

function AddBookModal({ onClose, onAdded }) {
  const [status, setStatus] = useState('"'reading');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  async function submit(event) {
    event.preventDefault();
    const data = Object.fromEntries(new FormData(event.currentTarget));
    setSaving(true); setError('');
    try { const book = await api('', { method: 'POST', body: JSON.stringify({ ...data, status }) }); onAdded(book); }
    catch (error) { setError(error.message); setSaving(false); }
  }
  return <Modal title=\"A new chapter awaits.\" subtitle=\"Add a book and make a little space for it on your shelf.\" onClose={onClose}><form onSubmit={submit}>
    <label className=\"field-label\" htmlFor=\"title\">Book title <span>*</span></label><input autoFocus id=\"title\" name=\"title\" placeholder=\"What are you reading?\" required maxLength={200} />
    <label className=\"field-label\" htmlFor=\"author\">Author <span>*</span></label><input id=\"author\" name=\"author\" placeholder=\"Who wrote it?\" required maxLength={200} />
    <fieldset className=\"status-field\"><legend className=\"field-label\">On my shelf</legend><div className=\"status-options\"><label className={status === 'reading' ? 'selected' : ''}><input type=\"radio\" name=\"status\" value=\"reading\" checked={status === 'reading'} onChange={() => setStatus('reading')} /><BookOpen size={17} /> Currently reading</label><label className={status === 'finished' ? 'selected' : ''}><input type=\"radio\" name=\"status\" value=\"finished\" checked={status === 'finished'} onChange={() => setStatus('finished')} /><BookCheck size={17} /> Finished</label></div></fieldset>
    <label className=\"field-label\" htmlFor=\"notes\">Your notes <span className=\"optional\">optional</span></label><textarea id=\"notes\" name=\"notes\" placeholder=\"A first impression, a favorite line, a thought to keep…\" rows={3} maxLength={20000} />
    {error && <p className=\"form-error\" role=\"alert\">{error}</p>}
    <div className=\"modal-actions\"><button type=\"button\" className=\"button secondary\" onClick={onClose}>Cancel</button><button className=\"button primary\" disabled={saving}>{saving ? <LoaderCircle className=\"spin\" size={17} /> : <Plus size={17} />}{saving ? 'Adding…' : 'Add to my library'}</button></div>
  </form></Modal>;
}

function BookCard({ book, onStatus, onDelete, onShare, compact = false }) {
  const [menu, setMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const menuRef = useRef(null);
  useEffect(() => {
    if ("'!menu) return;
    const close = event => { if (!menuRef.current?.contains(event.target) || event.key === '"'Escape') setMenu(false); };
    document.addEventListener('pointerdown', close); document.addEventListener('keydown', close);
    return () => { document.removeEventListener('pointerdown', close); document.removeEventListener('keydown', close); };
  }, [menu]);
  async function changeStatus() { setBusy(true); await onStatus(book, book.status === 'reading' ? 'finished' : 'reading'); setBusy(false); setMenu(false); }
  return <article className={"'`book-card ${compact ? '"'compact' : ''}"'`}>
    <Link className={`cover-stage ${book.color || '"'sand'}"'`} to={`/books/${book.id}`} aria-label={`View ${book.title}`}><BookCover book={book} /><span className="cover-view">Open book <ArrowRight size={15} /></span></Link>
    <div className="book-info"><div className="book-info-heading"><Link to={`/books/${book.id}`} className="book-title">{book.title}</Link><div className="book-menu" ref={menuRef}><button className="icon-button more-button" onClick={() => setMenu(!menu)} aria-label={`More options for ${book.title}`} aria-expanded={menu}><MoreHorizontal size={20} /></button>{menu && <div className="dropdown"><button onClick={changeStatus} disabled={busy}>{book.status === '"'reading' ? <Check size={15} /> : <BookOpen size={15} />}{book.status === 'reading' ? 'Mark as finished' : 'Read again'}</button><button onClick={() => { onShare(book); setMenu(false); }}><LinkIcon size={15} />Copy book link</button><button className=\"danger-text\" onClick={() => { onDelete(book); setMenu(false); }}><Trash2 size={15} />Remove book</button></div>}</div></div><p className=\"book-author\">{book.author}</p>
    {compact ? <div className=\"finished-date\"><CheckCheck size={14} /><span>Finished {new Date(book.finishedAt || book.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span></div> : <div className=\"card-bottom\"><span className=\"reading-label\"><span /> In progress</span><button className=\"finish-button\" onClick={changeStatus} disabled={busy}>{busy ? <LoaderCircle size={14} className=\"spin\" /> : <Check size={14} />} Mark as finished</button></div>}
    </div>
  </article>;
}

function LibraryPage({ books, filter, setFilter, onAdd, onStatus, onDelete, onShare, loading, error, reload }) {
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState('recent');
  const matches = books.filter(book => "'`${book.title} ${book.author}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => sort === '"'title' ? a.title.localeCompare(b.title) : sort === 'author' ? a.author.localeCompare(b.author) : new Date(b.createdAt) - new Date(a.createdAt));
  const reading = matches.filter(book => book.status === 'reading');
  const finished = matches.filter(book => book.status === 'finished');
  const count = status => books.filter(book => book.status === status).length;
  return <>
    <div className=\"page-heading\"><div><div className=\"eyebrow\">A LITTLE HOME FOR YOUR READING LIFE</div><h1>My library<span className=\"heading-dot\">.</span></h1><p>The books you’re in, and the ones that stay with you.</p></div><button className=\"button primary add-button\" onClick={onAdd}><Plus size={18} /> Add a book</button></div>
    <section className=\"library-summary\" aria-label=\"Reading summary\"><div className=\"summary-intro\"><div className=\"summary-illustration\"><BookOpen size={34} strokeWidth={1.2} /><span className=\"spark spark-one\">✧</span><span className=\"spark spark-two\">✦</span></div><div><h2>One page at a time.</h2><p>Every book is a place you’ve been.</p></div></div><div className=\"summary-stats\"><div><strong>{String(books.length).padStart(2, '0')}</strong><span>on your shelf</span></div><div><strong>{String(count('reading')).padStart(2, '0')}</strong><span>currently reading</span></div><div><strong>{String(count('finished')).padStart(2, '0')}</strong><span>finished books</span></div></div></section>
    <div className=\"library-toolbar\"><div className=\"tabs\" role=\"tablist\" aria-label=\"Filter books\">{[{ key: 'all', label: 'All books', count: books.length }, { key: 'reading', label: 'Currently reading', count: count('reading') }, { key: 'finished', label: 'Finished', count: count('finished') }].map(tab => <button key={tab.key} role=\"tab\" aria-selected={filter === tab.key} className={filter === tab.key ? 'active' : ''} onClick={() => setFilter(tab.key)}>{tab.label}<span>{tab.count}</span></button>)}</div><label className=\"search-field\"><Search size={16} /><input aria-label=\"Search books\" placeholder=\"Find a book…\" value={search} onChange={event => setSearch(event.target.value)} />{search && <button onClick={() => setSearch('')} aria-label=\"Clear search\"><X size={14} /></button>}</label></div>
    {loading ? <div className=\"loading-state\"><LoaderCircle className=\"spin\" /> Taking your books off the shelf…</div> : error ? <div className=\"empty-state\"><BookOpen size={35} /><h2>We couldn’t load your shelf.</h2><p>{error}</p><button className=\"button secondary\" onClick={reload}>Try again</button></div> : <>
    {filter "'!== '"'finished' && reading.length > 0 && <section className=\"book-section\"><div className=\"section-heading\"><div><h2><span className=\"section-dot\" />Currently reading <span className=\"section-count\">{reading.length}</span></h2><p>A few good worlds to get lost in.</p></div><label className=\"sort-control\"><ArrowDownWideNarrow size={14} /><select value={sort} onChange={event => setSort(event.target.value)} aria-label=\"Sort books\"><option value=\"recent\">Recently added</option><option value=\"title\">Book title</option><option value=\"author\">Author name</option></select><ChevronDown size={13} /></label></div><div className=\"book-grid\">{reading.map(book => <BookCard key={book.id} {...{ book, onStatus, onDelete, onShare }} />)}</div></section>}
    {filter "'!== '"'reading' && finished.length > 0 && <section className=\"book-section finished-section\"><div className=\"section-heading\"><div><h2><CheckCheck size={20} className=\"finished-icon\" />Finished <span className=\"section-count\">{finished.length}</span></h2><p>The last page is only the beginning.</p></div><span className=\"shelf-note\">Well read. Well remembered.</span></div><div className=\"book-grid finished-grid\">{finished.map(book => <BookCard key={book.id} {...{ book, onStatus, onDelete, onShare }} compact />)}</div></section>}
    {(filter === 'reading' ? reading.length === 0 : filter === 'finished' ? finished.length === 0 : matches.length === 0) && <div className=\"empty-state\"><BookOpen size={38} strokeWidth={1.3} /><h2>{search ? 'No books on this page.' : filter === 'finished' ? 'Good things take a few chapters.' : 'Your next chapter starts here.'}</h2><p>{search ? "'`We couldn’t find a book matching “${search}”. Try another title or author.` : filter === '"'finished' ? 'Mark a book as finished and you’ll find it right here.' : 'Add your first book and make this little shelf your own.'}</p>{search ? <button className=\"button secondary\" onClick={() => setSearch('')}>Clear search</button> : <button className=\"button primary\" onClick={onAdd}><Plus size={17} />Add a book</button>}</div>}
    </>}
    <footer className=\"page-footer\"><span><Feather size={14} /> A little less scrolling, a little more reading.</span><span>Your shelf. Your pace.</span></footer>
  </>;
}

function BookPage({ books, loading, error, onUpdate, onStatus, onDelete, onShare }) {
  const { id } = useParams();
  const book = books.find(book => book.id === id);
  const [notes, setNotes] = useState(book?.notes || '');
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState('');
  useEffect(() => { if ("'!editing) setNotes(book?.notes || '"''); }, [book?.notes, editing]);
  useEffect(() => { if (book) document.title = "'`${book.title} — Dogear`; return () => { document.title = '"'Dogear — Your personal reading room'; }; }, [book?.title]);
  useEffect(() => {
    if ("'!editing || notes === book?.notes) return;
    const warn = event => { event.preventDefault(); event.returnValue = '"''; };
    window.addEventListener('beforeunload', warn);
    return () => window.removeEventListener('beforeunload', warn);
  }, [editing, notes, book?.notes]);
  if (loading) return <div className=\"loading-state\"><LoaderCircle className=\"spin\" />Opening your book…</div>;
  if ("'!book) return <div className="empty-state"><BookOpen size={40} /><h1>{error ? '"'Your shelf is taking a moment.' : 'This shelf is missing a book.'}</h1><p>{error || 'The link may have changed, or this book may have been removed.'}</p><Link className=\"button primary\" to=\"/\">Back to my library</Link></div>;
  async function saveNotes() {
    setSaving(true); setFormError('');
    try { await onUpdate(book.id, { notes }); setEditing(false); } catch (error) { setFormError(error.message); } finally { setSaving(false); }
  }
  async function changeStatus() { setBusy(true); await onStatus(book, book.status === 'reading' ? 'finished' : 'reading'); setBusy(false); }
  return <div className=\"detail-page\"><div className=\"detail-topline\"><Link className=\"back-link\" to=\"/\"><ArrowLeft size={16} />Back to my library</Link><button className=\"button secondary share-button\" onClick={() => onShare(book)}><LinkIcon size={16} />Share book</button></div><div className=\"detail-layout\"><div className=\"detail-cover-column\"><div className={"'`detail-cover-stage ${book.color || '"'sand'}"'`}><BookCover book={book} /></div><p className="detail-cover-caption"><Bookmark size={14} />A chapter in your reading life.</p></div><div className="detail-content"><span className={`status-badge ${book.status}`}>{book.status === '"'reading' ? <BookOpen size={14} /> : <CheckCheck size={14} />}{book.status === 'reading' ? 'Currently reading' : 'Finished'}</span><h1>{book.title}</h1>{book.subtitle && <p className=\"book-subtitle\">{book.subtitle}</p>}<p className=\"detail-author\">by {book.author}</p><p className=\"detail-date\">{book.status === 'finished' ? "'`Finished on ${formatDate(book.finishedAt || book.createdAt)}` : `On your shelf since ${formatDate(book.createdAt)}`}</p><button className={`button ${book.status === '"'reading' ? 'primary' : 'secondary'}"'`} onClick={changeStatus} disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : book.status === '"'reading' ? <Check size={17} /> : <BookOpen size={17} />}{book.status === 'reading' ? 'Mark as finished' : 'Read this book again'}</button><section className=\"notes-section\"><div className=\"notes-heading\"><h2><FileText size={19} strokeWidth={1.5} />My notes</h2>{"'!editing && <button className="text-button" onClick={() => setEditing(true)}>{book.notes ? '"'Edit notes' : 'Add notes'}<Feather size={14} /></button>}</div>{editing ? <><label className=\"sr-only\" htmlFor=\"book-notes\">My notes</label><textarea autoFocus id=\"book-notes\" className=\"notes-editor\" value={notes} onChange={event => setNotes(event.target.value)} maxLength={20000} rows={9} placeholder=\"A favorite line, an idea, a thought to come back to…\" /><div className=\"notes-actions\"><span>{notes.length.toLocaleString()} / 20,000</span><button className=\"button secondary\" onClick={() => setEditing(false)} disabled={saving}>Cancel</button><button className=\"button primary\" onClick={saveNotes} disabled={saving}>{saving ? <LoaderCircle size={15} className=\"spin\" /> : <Check size={15} />}{saving ? 'Saving…' : 'Save notes'}</button></div>{formError && <p role=\"alert\" className=\"form-error\">{formError}</p>}</> : <div className={"'`notes-paper ${!book.notes ? '"'no-notes' : ''}"'`}>{book.notes || '"'Leave a little of yourself between the pages. Save a quote, a thought, or something you don’t want to forget.'}</div>}</section><button className=\"remove-book\" onClick={() => onDelete(book)}><Trash2 size={14} />Remove from my library</button></div></div><footer className=\"page-footer\"><span><Feather size={14} />Some stories stay with you.</span><span>Your shelf. Your pace.</span></footer></div>;
}

function App() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('all');
  const [adding, setAdding] = useState(false);
  const [deleting, setDeleting] = useState(null);
  const [deleteBusy, setDeleteBusy] = useState(false);
  const [deleteError, setDeleteError] = useState('');
  const [about, setAbout] = useState(false);
  const [share, setShare] = useState(null);
  const [toast, setToast] = useState(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const toastTimer = useRef(null);
  const navigate = useNavigate();
  async function reload() { setLoading(true); setError(''); try { setBooks(await api()); } catch (error) { setError(error.message); } finally { setLoading(false); } }
  useEffect(() => { reload(); return () => clearTimeout(toastTimer.current); }, []);
  function notify(message, isError = false) { clearTimeout(toastTimer.current); setToast({ message, isError }); toastTimer.current = setTimeout(() => setToast(null), 4200); }
  async function onUpdate(id, data) { const book = await api("'`/${id}`, { method: '"'PATCH', body: JSON.stringify(data) }); setBooks(previous => previous.map(item => item.id === id ? book : item)); notify('Your notes are saved.'); return book; }
  async function onStatus(book, status) { try { const updated = await api("'`/${book.id}`, { method: '"'PATCH', body: JSON.stringify({ status }) }); setBooks(previous => previous.map(item => item.id === book.id ? updated : item)); notify(status === 'finished' ? 'Another story finished. Onto the next chapter"'!'"' : 'Back on your currently reading shelf.'); } catch (error) { notify(error.message, true); } }
  async function onShare(book) {
    const url = "'`${window.location.origin}/books/${book.id}`;
    try { await navigator.clipboard.writeText(url); notify('"'Book link copied. Share a little good reading.'); } catch { setShare({ url, title: book.title }); }
  }
  async function removeBook() { setDeleteBusy(true); setDeleteError(''); try { await api("'`/${deleting.id}`, { method: '"'DELETE' }); setBooks(previous => previous.filter(book => book.id "'!== deleting.id)); if (window.location.pathname === `/books/${deleting.id}`) navigate('"'/'); setDeleting(null); notify('Book removed from your library.'); } catch (error) { setDeleteError(error.message); } finally { setDeleteBusy(false); } }
  function navTo(nextFilter) { setFilter(nextFilter); setMobileOpen(false); navigate('/'); }
  return <div className=\"app-shell\">
    {mobileOpen && <div className=\"sidebar-overlay\" onClick={() => setMobileOpen(false)} />}
    <aside className={"'`sidebar ${mobileOpen ? '"'mobile-open' : ''}"'`}><Brand /><div className="sidebar-tagline">Your personal reading room</div><div className="nav-group-label">THE BOOKSHELF</div><nav className="main-nav" aria-label="Main navigation"><button className={filter === '"'all' ? 'active' : ''} onClick={() => navTo('all')}><Library size={19} strokeWidth={1.6} /><span>My library</span><span className=\"nav-count\">{books.length}</span></button><button className={filter === 'reading' ? 'active' : ''} onClick={() => navTo('reading')}><BookOpen size={19} strokeWidth={1.6} /><span>Currently reading</span><span className=\"nav-count\">{books.filter(book => book.status === 'reading').length}</span></button><button className={filter === 'finished' ? 'active' : ''} onClick={() => navTo('finished')}><BookCheck size={19} strokeWidth={1.6} /><span>Finished</span><span className=\"nav-count\">{books.filter(book => book.status === 'finished').length}</span></button></nav><button className=\"sidebar-add\" onClick={() => { setAdding(true); setMobileOpen(false); }}><Plus size={17} />Add a book</button><div className=\"sidebar-bottom\"><div className=\"quote-card\"><span className=\"quote-mark\">“</span><p>There is no friend<br />as loyal as a book.</p><span className=\"quote-author\">— Ernest Hemingway</span><div className=\"quote-drawing\"><span className=\"drawn-book book-one\" /><span className=\"drawn-book book-two\" /><span className=\"drawn-book book-three\" /><Feather size={47} strokeWidth={0.8} /></div></div><button className=\"about-link\" onClick={() => setAbout(true)}><CircleHelp size={17} strokeWidth={1.5} />A note about Dogear<ArrowUpRightSmall /></button><div className=\"sidebar-bottom-note\">Made for the love of reading.<span>Take your time. Stay a while.</span></div></div></aside>
    <div className=\"main-wrapper\"><header className=\"topbar\"><div className=\"topbar-left\"><button className=\"icon-button mobile-menu\" onClick={() => setMobileOpen(true)} aria-label=\"Open navigation\"><Menu size={21} /></button><span className=\"topbar-book\"><BookOpen size={16} strokeWidth={1.5} /></span><span>My reading room</span><ChevronRight size={13} /><span className=\"topbar-current\">The bookshelf</span></div><div className=\"topbar-right\"><span className=\"tiny-dot\" />A good day for a good book<Bookmark size={17} strokeWidth={1.4} /></div></header><main><Routes><Route path=\"/\" element={<LibraryPage {...{ books, filter, setFilter, onStatus, onShare, loading, error, reload }} onAdd={() => setAdding(true)} onDelete={book => { setDeleteError(''); setDeleting(book); }} />} /><Route path=\"/books/:id\" element={<BookPage {...{ books, loading, error, onUpdate, onStatus, onShare }} onDelete={book => { setDeleteError(''); setDeleting(book); }} />} /><Route path=\"*\" element={<div className=\"empty-state\"><BookOpen size={38} /><h1>A page out of place.</h1><p>Let’s get you back to your bookshelf.</p><Link to=\"/\" className=\"button primary\">Back to my library</Link></div>} /></Routes></main></div>
    {adding && <AddBookModal onClose={() => setAdding(false)} onAdded={book => { setBooks(previous => [book, ...previous]); setAdding(false); setFilter('all'); navigate("'`/books/${book.id}`); notify('"'A new book, a new beginning. Added to your shelf.'); }} />}
    {deleting && <Modal small title=\"Make room on your shelf?\" subtitle={"'`“${deleting.title}” and its notes will be removed from your library.`} onClose={() => { if (!deleteBusy) setDeleting(null); }}><p className="delete-note">This can’t be undone.</p>{deleteError && <p className="form-error" role="alert">{deleteError}</p>}<div className="modal-actions"><button className="button secondary" onClick={() => setDeleting(null)} disabled={deleteBusy}>Keep book</button><button className="button danger" onClick={removeBook} disabled={deleteBusy}>{deleteBusy ? <LoaderCircle className="spin" size={16} /> : <Trash2 size={16} />}Remove book</button></div></Modal>}
    {about && <Modal small title="A little space for stories." subtitle="Dogear is your personal reading room." onClose={() => setAbout(false)}><div className="about-copy"><p>Keep the books you’re reading close, remember the ones you’ve finished, and leave a few thoughts along the way.</p><p>Use <strong>Share book</strong> to send someone a link to a book and its notes. Anyone with access to this app can view and edit the shared library.</p><p>We’ve put a few sample books on the shelf to get you started. Keep them, or make room for your own.</p><span className="about-signoff">No goals to chase. Just good books.</span></div><button className="button primary full-width" onClick={() => setAbout(false)}>Back to the books<ArrowRight size={16} /></button></Modal>}
    {share && <Modal small title="Good books are better shared." subtitle={share.title} onClose={() => setShare(null)}><label className="field-label" htmlFor="share-url">Book link</label><input id="share-url" readOnly value={share.url} onFocus={event => event.target.select()} /><p className="share-help">Copy this link to share the book and your notes.</p><button className="button primary full-width" onClick={() => setShare(null)}>Done<Check size={16} /></button></Modal>}
    {toast && <div className={`toast ${toast.isError ? '"'error-toast' : ''}"'`} role={toast.isError ? '"'alert' : 'status'}>{toast.isError ? <CircleHelp size={18} /> : <span className=\"toast-check\"><Check size={14} /></span>}{toast.message}<button onClick={() => setToast(null)} aria-label=\"Dismiss notification\"><X size={15} /></button></div>}
  </div>;
}
