  await expect(direct.getByRole('heading',{name:'My library.'})).toBeVisible();
  await direct.goto(bookUrl);
  await expect(direct.getByRole('heading',{name:'This shelf is missing a book.'})).toBeVisible();
  const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
  await mobile.goto('http://localhost:3000');
  await expect(mobile.locator('.book-card')).toHaveCount(6);
  await mobile.evaluate(()=>document.fonts.ready);
  await mobile.screenshot({path:'/tmp/dogear-mobile.png',fullPage:true,animations:'disabled'});
  if(await mobile.evaluate(()=>document.documentElement.scrollWidth)>390)throw new Error('Mobile overflow');
  const sidebarBox = await mobile.locator('.sidebar').boundingBox();
  if(sidebarBox.x + sidebarBox.width > 1)throw new Error('Sidebar visible on mobile');
  await mobile.getByRole('button',{name:'Open navigation'}).click();
  await mobile.getByRole('navigation').getByRole('button',{name:'Finished'}).click();
  await expect(mobile.locator('.book-card')).toHaveCount(3);
  await mobile.locator('.add-button').click();
  await expect(mobile.getByRole('dialog')).toBeVisible();
  await mobile.getByRole('button',{name:'Close dialog'}).click();
  if(errors.length)throw new Error(errors.join('\\n'));
  console.log('PASS: add book, edit notes, mark finished, clipboard share, direct links, server restart persistence, refresh, filters, search, delete confirmation, missing book, mobile navigation and dialog. No browser errors.');
} finally { await browser?.close(); await stop(); await rm(directory,{recursive:true,force:true}); }
