import urllib.request, concurrent.futures
books={'creative-act':'9780593652886','midnight-library':'9780525559474','gentleman-in-moscow':'9780670026197','atomic-habits':'9780735211292','alchemist':'9780061122415','psychology-of-money':'9780857197689'}
def get(item):
 name,isbn=item
 try:
  req=urllib.request.Request(f'https://covers.openlibrary.org/b/isbn/{isbn}-L.jpg',headers={'User-Agent':'Mozilla/5.0'})
  data=urllib.request.urlopen(req,timeout=25).read()
  if len(data)>1000:
   open(f'public/covers/{name}.jpg','wb').write(data)
   return name,len(data)
  return name,'no cover'
 except Exception as e: return name,str(e)
with concurrent.futures.ThreadPoolExecutor() as pool:
 for result in pool.map(get,books.items()): print(result)
PY"

