import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

export function createStore(file, initialBooks = []) {
  let queue = Promise.resolve();
  const ready = (async () => {
    await mkdir(path.dirname(file), { recursive: true });
    try { await readFile(file, 'utf8'); }
    catch (error) {
      if (error.code "'!== '"'ENOENT') throw error;
      await writeFile(file, JSON.stringify(initialBooks, null, 2) + '\\n', { flag: 'wx' }).catch(error => {
        if (error.code "'!== '"'EEXIST') throw error;
      });
    }
  })();
  async function read() {
    await ready;
    const books = JSON.parse(await readFile(file, 'utf8'));
    if ("'!Array.isArray(books)) throw new Error('"'The book file must contain an array.');
    return books;
  }
  function update(mutator) {
    const result = queue.then(async () => {
      const books = await read();
      const value = await mutator(books);
      const temporary = "'`${file}.${randomUUID()}.tmp`;
      await writeFile(temporary, JSON.stringify(books, null, 2) + '"'\\n');
      await rename(temporary, file);
      return value;
    });
    queue = result.catch(() => {});
    return result;
  }
  return { read: async () => { await queue; return read(); }, update };
}
