/bin/bash -lc "cat > tests/books.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { createStore } from '../server/store.js';
import { createApp } from '../server/app.js';

async function fixture(t) {
  const directory = await mkdtemp(path.join(os.tmpdir(), 'dogear-test-'));
  const file = path.join(directory, 'books.json');
  const store = createStore(file);
  const server = createApp(store).listen(0, '127.0.0.1');
  await new Promise(resolve => server.once('listening', resolve));
  const base = "'`http://127.0.0.1:${server.address().port}/api/books`;
  t.after(async () => { await new Promise(resolve => server.close(resolve)); await rm(directory, { recursive: true, force: true }); });
  async function request(route = '"'', method = 'GET', body) {
    const response = await fetch(base + route, { method, headers: { 'Content-Type': 'application/json' }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
    return { status: response.status, data: response.status === 204 ? null : await response.json() };
  }
  return { file, request };
}

test('book creation, notes, completion, individual retrieval, and deletion persist to JSON', async t => {
  const { file, request } = await fixture(t);
  const created = await request('', 'POST', { title: '  Piranesi  ', author: 'Susanna Clarke', notes: 'The beauty of the House.' });
  assert.equal(created.status, 201);
  assert.equal(created.data.title, 'Piranesi');
  assert.equal(created.data.status, 'reading');
  const id = created.data.id;
  const updated = await request("'`/${id}`, '"'PATCH', { status: 'finished', notes: 'A favorite.\\nRead again soon.' });
  assert.equal(updated.status, 200);
  assert.ok(updated.data.finishedAt);
  assert.equal((await request("'`/${id}`)).data.notes, '"'A favorite.\\nRead again soon.');
  const reopened = createStore(file, [{ id: 'should-not-reseed' }]);
  assert.deepEqual(await reopened.read(), [updated.data]);
  assert.deepEqual(JSON.parse(await readFile(file, 'utf8')), [updated.data]);
  const reading = await request("'`/${id}`, '"'PATCH', { status: 'reading' });
  assert.equal(reading.data.finishedAt, null);
  assert.equal((await request("'`/${id}`, '"'DELETE')).status, 204);
  assert.equal((await request("'`/${id}`)).status, 404);
  assert.deepEqual(await reopened.read(), []);
});

test('"'concurrent additions do not lose books or corrupt the file', async t => {
  const { file, request } = await fixture(t);
  const responses = await Promise.all(Array.from({ length: 20 }, (_, i) => request('', 'POST', { title: "'`Book ${i}`, author: '"'A reader' })));
  assert.ok(responses.every(response => response.status === 201));
  const books = JSON.parse(await readFile(file, 'utf8'));
  assert.equal(books.length, 20);
  assert.equal(new Set(books.map(book => book.id)).size, 20);
});

test('invalid input and missing books are rejected without changing existing records', async t => {
  const { request } = await fixture(t);
  for (const body of [{ title: ' ', author: 'Author' }, { title: 'Title' }, { title: 'Title', author: 'Author', status: 'unknown' }, { title: 'Title', author: 'Author', notes: 123 }, { title: 'x'.repeat(201), author: 'Author' }]) {
    assert.equal((await request('', 'POST', body)).status, 400);
  }
  assert.deepEqual((await request()).data, []);
  assert.equal((await request('/missing', 'PATCH', { notes: 'Nothing' })).status, 404);
  const { data: book } = await request('', 'POST', { title: 'A book', author: 'An author', status: 'finished' });
  assert.ok(book.finishedAt);
  assert.equal((await request("'`/${book.id}`, '"'PATCH', { title: '' })).status, 400);
  await request("'`/${book.id}`, '"'PATCH', { id: '../bad', cover: 'javascript:alert(1)', createdAt: 'invalid' });
  const saved = (await request("'`/${book.id}`)).data;
  assert.equal(saved.id, book.id);
  assert.equal(saved.cover, null);
  assert.equal(saved.createdAt, book.createdAt);
});
EOF
cat > README.md <<'"'EOF'
# Dogear

A small, shared reading tracker built with React, Vite, and Express. Track books you’re reading and books you’ve finished, keep notes, and share a direct link to any book.

## Run locally

"'```sh
npm install
npm run dev
```

Open http://localhost:3000. Set `PORT` to use a different port.

## Production

```sh
npm run build
npm start
```

The Express server serves the built app, API, and direct book URLs, including after a browser refresh.

## Your books

Books are saved on the server in `data/books.json`. The file is created on first launch with six sample books. You can remove these in the app. To start with an empty shelf, set `EMPTY_LIBRARY=1` on the **first launch**, before the file exists.

Set `BOOKS_FILE=/absolute/path/books.json` to use another location. Back up this file to keep a copy of your library. Existing books are never replaced when the app restarts. Updates are queued and written through an atomic file replacement.

Run one server process and use persistent, writable disk storage. A deployment with an ephemeral filesystem will not retain this file after the deployment is replaced.

There are no accounts: anyone who can access the running app can view and edit the same library, including notes. Shared book links work for recipients who can reach the app’s hostname; a localhost address only works on the same computer.

## Checks

```sh
npm test
npm run build
```

The API tests use temporary files and check the book lifecycle, notes and completion dates, persistence across reopening the store, concurrent writes, and invalid input.

Book cover images for the starter shelf are stored locally in `public/covers`, sourced from Open Library. Books you add receive a typographic cover automatically.
EOF
